package com.landportal.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="acquisition_cases") public class AcquisitionCase { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true) String caseNumber; @ManyToOne(optional=false) Parcel parcel; String projectName; double affectedArea; @Enumerated(EnumType.STRING) CaseStatus status; LocalDateTime createdAt; public Long getId(){return id;} public String getCaseNumber(){return caseNumber;} public void setCaseNumber(String v){caseNumber=v;} public Parcel getParcel(){return parcel;} public void setParcel(Parcel v){parcel=v;} public String getProjectName(){return projectName;} public void setProjectName(String v){projectName=v;} public double getAffectedArea(){return affectedArea;} public void setAffectedArea(double v){affectedArea=v;} public CaseStatus getStatus(){return status;} public void setStatus(CaseStatus v){status=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} @PrePersist void init(){createdAt=LocalDateTime.now(); if(status==null)status=CaseStatus.IDENTIFIED;} }
